-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.quota_cards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer;
begin
  if tg_op = 'DELETE' then
    update public.user_quotas set cards = greatest(cards - 1, 0) where user_id = old.user_id;
    return null;
  end if;
  insert into public.user_quotas as q (user_id, cards) values (new.user_id, 1)
  on conflict (user_id) do update set cards = q.cards + 1
  returning q.cards into n;
  if n > 200000 then
    raise exception 'quota_exceeded' using errcode = 'P0001', detail = 'cards';
  end if;
  return null;
end;
$function$;

grant execute on function public.quota_cards() to service_role;
